DDL = "\nCREATE TABLE cehub_project.value_measurement_workpacks (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tstudy_id UUID NOT NULL, \n\ttask_id UUID NOT NULL, \n\tmode VARCHAR(24) NOT NULL, \n\tcreator_user_id UUID NOT NULL, \n\tdeliverer_user_id UUID NOT NULL, \n\treceiver_user_id UUID NOT NULL, \n\tbody JSONB NOT NULL, \n\tsource_snapshot JSONB NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_value_measurement_workpacks PRIMARY KEY (id), \n\tCONSTRAINT fk_value_pack_study FOREIGN KEY(tenant_id, project_id, study_id) REFERENCES cehub_project.value_measurement_studies (tenant_id, project_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_pack_task FOREIGN KEY(tenant_id, project_id, task_id) REFERENCES cehub_project.tasks (tenant_id, project_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_pack_creator_user_id FOREIGN KEY(tenant_id, creator_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_pack_deliverer_user_id FOREIGN KEY(tenant_id, deliverer_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_pack_receiver_user_id FOREIGN KEY(tenant_id, receiver_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_value_pack_scope UNIQUE (tenant_id, project_id, id), \n\tCONSTRAINT uq_value_pack_study_scope UNIQUE (tenant_id, project_id, study_id, id), \n\tCONSTRAINT uq_value_pack_task_mode UNIQUE (tenant_id, study_id, task_id, mode), \n\tCONSTRAINT uq_value_pack_request UNIQUE (tenant_id, creator_user_id, request_id), \n\tCONSTRAINT ck_value_measurement_workpacks_independent_roles CHECK (deliverer_user_id<>receiver_user_id AND mode IN ('baseline_without_ai','assisted')), \n\tCONSTRAINT ck_value_measurement_workpacks_scope_shape CHECK (jsonb_typeof(body)='object' AND jsonb_typeof(source_snapshot)='object' AND body->>'full_roster_confirmed'='true'), \n\tCONSTRAINT ck_value_measurement_workpacks_request_digest CHECK (request_digest ~ '^[a-f0-9]{64}$')\n)\n\n;\nCREATE INDEX ix_value_pack_project_study ON cehub_project.value_measurement_workpacks (tenant_id, project_id, study_id, id);\n\nCREATE TABLE cehub_project.value_measurement_workpack_members (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tworkpack_id UUID NOT NULL, \n\tuser_id UUID NOT NULL, \n\trole_id VARCHAR(128) NOT NULL, \n\tfirst_use BOOLEAN NOT NULL, \n\tCONSTRAINT pk_value_measurement_workpack_members PRIMARY KEY (id), \n\tCONSTRAINT fk_value_pack_member_pack FOREIGN KEY(tenant_id, project_id, workpack_id) REFERENCES cehub_project.value_measurement_workpacks (tenant_id, project_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_pack_member_user FOREIGN KEY(tenant_id, user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_value_pack_member UNIQUE (tenant_id, project_id, workpack_id, user_id), \n\tCONSTRAINT ck_value_measurement_workpack_members_role_nonblank CHECK (btrim(role_id)<>'')\n)\n\n;\n\n\nCREATE TABLE cehub_project.value_measurement_deliveries (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tstudy_id UUID NOT NULL, \n\tworkpack_id UUID NOT NULL, \n\tround INTEGER NOT NULL, \n\tactor_user_id UUID NOT NULL, \n\treceiver_user_id UUID NOT NULL, \n\tdeliverer_consent_id UUID NOT NULL, \n\treceiver_consent_id UUID NOT NULL, \n\tdocument_id UUID NOT NULL, \n\tlocator TEXT NOT NULL, \n\tdescription TEXT NOT NULL, \n\tsource_snapshot JSONB NOT NULL, \n\tsource_digest VARCHAR(64) NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_value_measurement_deliveries PRIMARY KEY (id), \n\tCONSTRAINT fk_value_delivery_pack FOREIGN KEY(tenant_id, project_id, study_id, workpack_id) REFERENCES cehub_project.value_measurement_workpacks (tenant_id, project_id, study_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_delivery_document FOREIGN KEY(tenant_id, project_id, document_id) REFERENCES cehub_project.documents (tenant_id, project_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_delivery_sender_consent FOREIGN KEY(tenant_id, project_id, study_id, actor_user_id, deliverer_consent_id) REFERENCES cehub_project.value_measurement_consents (tenant_id, project_id, study_id, participant_user_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_delivery_receiver_consent FOREIGN KEY(tenant_id, project_id, study_id, receiver_user_id, receiver_consent_id) REFERENCES cehub_project.value_measurement_consents (tenant_id, project_id, study_id, participant_user_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_value_delivery_scope UNIQUE (tenant_id, project_id, workpack_id, id), \n\tCONSTRAINT uq_value_delivery_round UNIQUE (tenant_id, project_id, workpack_id, round), \n\tCONSTRAINT uq_value_delivery_request UNIQUE (tenant_id, actor_user_id, request_id), \n\tCONSTRAINT ck_value_measurement_deliveries_round_content CHECK (round>0 AND actor_user_id<>receiver_user_id AND btrim(locator)<>'' AND btrim(description)<>''), \n\tCONSTRAINT ck_value_measurement_deliveries_source_digests CHECK (source_digest ~ '^[a-f0-9]{64}$' AND request_digest ~ '^[a-f0-9]{64}$' AND jsonb_typeof(source_snapshot)='object')\n)\n\n;\n\n\nCREATE TABLE cehub_project.value_measurement_receptions (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tstudy_id UUID NOT NULL, \n\tworkpack_id UUID NOT NULL, \n\tdelivery_id UUID NOT NULL, \n\tactor_user_id UUID NOT NULL, \n\treceiver_consent_id UUID NOT NULL, \n\tdecision VARCHAR(16) NOT NULL, \n\tcriteria_checked BOOLEAN NOT NULL, \n\treason TEXT NOT NULL, \n\tsource_snapshot JSONB NOT NULL, \n\tsource_digest VARCHAR(64) NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_value_measurement_receptions PRIMARY KEY (id), \n\tCONSTRAINT fk_value_reception_delivery FOREIGN KEY(tenant_id, project_id, workpack_id, delivery_id) REFERENCES cehub_project.value_measurement_deliveries (tenant_id, project_id, workpack_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_reception_consent FOREIGN KEY(tenant_id, project_id, study_id, actor_user_id, receiver_consent_id) REFERENCES cehub_project.value_measurement_consents (tenant_id, project_id, study_id, participant_user_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_value_reception_delivery UNIQUE (tenant_id, delivery_id), \n\tCONSTRAINT uq_value_reception_request UNIQUE (tenant_id, actor_user_id, request_id), \n\tCONSTRAINT ck_value_measurement_receptions_decision_content CHECK (decision IN ('accepted','returned') AND criteria_checked AND btrim(reason)<>''), \n\tCONSTRAINT ck_value_measurement_receptions_source_digests CHECK (source_digest ~ '^[a-f0-9]{64}$' AND request_digest ~ '^[a-f0-9]{64}$' AND jsonb_typeof(source_snapshot)='object')\n)\n\n;\nCREATE INDEX ix_value_reception_pack ON cehub_project.value_measurement_receptions (tenant_id, workpack_id);\n\nCREATE TABLE cehub_project.value_measurement_closures (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tworkpack_id UUID NOT NULL, \n\tactor_user_id UUID NOT NULL, \n\toutcome VARCHAR(16) NOT NULL, \n\treason TEXT NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_value_measurement_closures PRIMARY KEY (id), \n\tCONSTRAINT fk_value_closure_pack FOREIGN KEY(tenant_id, project_id, workpack_id) REFERENCES cehub_project.value_measurement_workpacks (tenant_id, project_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_value_closure_actor FOREIGN KEY(tenant_id, actor_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_value_closure_pack UNIQUE (tenant_id, project_id, workpack_id), \n\tCONSTRAINT uq_value_closure_request UNIQUE (tenant_id, actor_user_id, request_id), \n\tCONSTRAINT ck_value_measurement_closures_closure_content CHECK (outcome IN ('failed','cancelled') AND btrim(reason)<>'' AND request_digest ~ '^[a-f0-9]{64}$')\n)\n\n;\n"

GUARDS = "CREATE FUNCTION cehub_project.guard_value_workpack() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE s cehub_project.value_measurement_studies;\nBEGIN\n PERFORM 1 FROM cehub_project.projects WHERE tenant_id=NEW.tenant_id AND id=NEW.project_id FOR UPDATE;\n SELECT * INTO s FROM cehub_project.value_measurement_studies WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.study_id;\n IF s.id IS NULL OR NEW.created_at>=s.window_end\n  OR NEW.body->>'study_id' IS DISTINCT FROM NEW.study_id::text\n  OR NEW.body->>'task_id' IS DISTINCT FROM NEW.task_id::text\n  OR NEW.body->>'mode' IS DISTINCT FROM NEW.mode\n  OR NEW.body->>'deliverer_user_id' IS DISTINCT FROM NEW.deliverer_user_id::text\n  OR NEW.body->>'receiver_user_id' IS DISTINCT FROM NEW.receiver_user_id::text\n  OR NEW.body->>'evidence_kind' IS DISTINCT FROM s.evidence_kind\n  OR NEW.body->>'scenario_id' IS DISTINCT FROM s.protocol->>'scenario_id'\n  OR NEW.body->>'full_roster_confirmed' IS DISTINCT FROM 'true'\n  OR NOT coalesce(s.protocol->'complexity_strata' ? (NEW.body->>'complexity_stratum'),false)\n  OR coalesce(btrim(NEW.body->>'workflow_version'),'')=''\n  OR coalesce(btrim(NEW.body->>'scope'),'')='' OR coalesce(btrim(NEW.body->>'completion_criteria'),'')=''\n  OR (NEW.body->>'pair_key' IS NULL)<>(NEW.body->>'matching_basis' IS NULL)\n THEN RAISE EXCEPTION 'Workpack must fix the registered study, scope and comparison identity'; END IF;\n IF jsonb_typeof(NEW.body->'members') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Workpack requires an explicit full roster'; END IF;\n IF jsonb_array_length(NEW.body->'members') NOT BETWEEN 2 AND 20\n  OR (SELECT count(DISTINCT x->>'user_id') FROM jsonb_array_elements(NEW.body->'members') x)<>jsonb_array_length(NEW.body->'members')\n  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.body->'members') x WHERE x->>'user_id'=NEW.deliverer_user_id::text)\n  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.body->'members') x WHERE x->>'user_id'=NEW.receiver_user_id::text)\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.body->'members') x WHERE NOT coalesce(s.protocol->'role_ids' ? (x->>'role_id'),false) OR jsonb_typeof(x->'first_use') IS DISTINCT FROM 'boolean'\n   OR NOT EXISTS(SELECT 1 FROM cehub_project.project_members m JOIN cehub_core.users u ON u.tenant_id=m.tenant_id AND u.id=m.user_id WHERE m.tenant_id=NEW.tenant_id AND m.project_id=NEW.project_id AND m.user_id=(x->>'user_id')::uuid AND u.is_active))\n THEN RAISE EXCEPTION 'Roster must name unique active actual project members, registered roles and independent receiver'; END IF;\n IF s.evidence_kind='real_business' AND (EXISTS(SELECT 1 FROM cehub_project.value_measurement_samples v WHERE v.tenant_id=NEW.tenant_id AND v.study_id=NEW.study_id AND v.task_id=NEW.task_id) OR EXISTS(SELECT 1 FROM cehub_project.value_measurement_workpacks v WHERE v.tenant_id=NEW.tenant_id AND v.study_id=NEW.study_id AND v.task_id=NEW.task_id))\n THEN RAISE EXCEPTION 'A real workpack must be registered before its participant observations'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_project.guard_value_workpack_roster() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nBEGIN\n IF (SELECT count(*) FROM cehub_project.value_measurement_workpack_members m WHERE m.tenant_id=NEW.tenant_id AND m.project_id=NEW.project_id AND m.workpack_id=NEW.id)<>jsonb_array_length(NEW.body->'members')\n THEN RAISE EXCEPTION 'Workpack and complete roster must be recorded together'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_project.guard_value_workpack_member() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE p cehub_project.value_measurement_workpacks;\nBEGIN\n PERFORM 1 FROM cehub_project.projects WHERE tenant_id=NEW.tenant_id AND id=NEW.project_id FOR UPDATE;\n SELECT * INTO p FROM cehub_project.value_measurement_workpacks WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.workpack_id;\n IF p.id IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.body->'members') x WHERE x->>'user_id'=NEW.user_id::text AND x->>'role_id'=NEW.role_id AND (x->>'first_use')::boolean=NEW.first_use)\n THEN RAISE EXCEPTION 'Actual member row must match the immutable workpack roster'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_project.guard_value_delivery() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE p cehub_project.value_measurement_workpacks;\nDECLARE s cehub_project.value_measurement_studies;\nDECLARE prev cehub_project.value_measurement_deliveries;\nDECLARE sender_grant cehub_project.value_measurement_consents;\nDECLARE receiver_grant cehub_project.value_measurement_consents;\nBEGIN\n PERFORM 1 FROM cehub_project.projects WHERE tenant_id=NEW.tenant_id AND id=NEW.project_id FOR UPDATE;\n SELECT * INTO p FROM cehub_project.value_measurement_workpacks WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.workpack_id;\n SELECT * INTO s FROM cehub_project.value_measurement_studies WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=p.study_id;\n SELECT * INTO prev FROM cehub_project.value_measurement_deliveries WHERE tenant_id=NEW.tenant_id AND workpack_id=NEW.workpack_id ORDER BY round DESC LIMIT 1;\n SELECT * INTO sender_grant FROM cehub_project.value_measurement_consents WHERE tenant_id=NEW.tenant_id AND study_id=p.study_id AND participant_user_id=p.deliverer_user_id ORDER BY version DESC LIMIT 1;\n SELECT * INTO receiver_grant FROM cehub_project.value_measurement_consents WHERE tenant_id=NEW.tenant_id AND study_id=p.study_id AND participant_user_id=p.receiver_user_id ORDER BY version DESC LIMIT 1;\n IF p.id IS NULL OR NEW.study_id IS DISTINCT FROM p.study_id OR NEW.actor_user_id IS DISTINCT FROM p.deliverer_user_id OR NEW.receiver_user_id IS DISTINCT FROM p.receiver_user_id\n  OR NEW.round<>coalesce(prev.round,0)+1 OR NEW.created_at<p.created_at OR NEW.created_at<s.window_start OR NEW.created_at>=s.window_end\n  OR EXISTS(SELECT 1 FROM cehub_project.value_measurement_closures WHERE tenant_id=NEW.tenant_id AND workpack_id=NEW.workpack_id)\n  OR (prev.id IS NOT NULL AND (NEW.created_at<prev.created_at OR NOT EXISTS(SELECT 1 FROM cehub_project.value_measurement_receptions r WHERE r.tenant_id=NEW.tenant_id AND r.delivery_id=prev.id AND r.decision='returned' AND r.created_at<=NEW.created_at)))\n THEN RAISE EXCEPTION 'Delivery must append a permitted next round by the named deliverer'; END IF;\n IF sender_grant.id IS DISTINCT FROM NEW.deliverer_consent_id OR sender_grant.status IS DISTINCT FROM 'consented' OR NOT sender_grant.activity_and_aggregate_use_confirmed OR sender_grant.created_at>NEW.created_at\n  OR receiver_grant.id IS DISTINCT FROM NEW.receiver_consent_id OR receiver_grant.status IS DISTINCT FROM 'consented' OR NOT receiver_grant.activity_and_aggregate_use_confirmed OR receiver_grant.created_at>NEW.created_at\n THEN RAISE EXCEPTION 'Delivery requires current separate participant grants'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_project.guard_value_reception() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE p cehub_project.value_measurement_workpacks;\nDECLARE s cehub_project.value_measurement_studies;\nDECLARE d cehub_project.value_measurement_deliveries;\nDECLARE receiver_grant cehub_project.value_measurement_consents;\nDECLARE sender_grant cehub_project.value_measurement_consents;\nBEGIN\n PERFORM 1 FROM cehub_project.projects WHERE tenant_id=NEW.tenant_id AND id=NEW.project_id FOR UPDATE;\n SELECT * INTO p FROM cehub_project.value_measurement_workpacks WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.workpack_id;\n SELECT * INTO s FROM cehub_project.value_measurement_studies WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=p.study_id;\n SELECT * INTO d FROM cehub_project.value_measurement_deliveries WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND workpack_id=NEW.workpack_id AND id=NEW.delivery_id;\n SELECT * INTO receiver_grant FROM cehub_project.value_measurement_consents WHERE tenant_id=NEW.tenant_id AND study_id=p.study_id AND participant_user_id=p.receiver_user_id ORDER BY version DESC LIMIT 1;\n SELECT * INTO sender_grant FROM cehub_project.value_measurement_consents WHERE tenant_id=NEW.tenant_id AND study_id=p.study_id AND participant_user_id=p.deliverer_user_id ORDER BY version DESC LIMIT 1;\n IF p.id IS NULL OR d.id IS NULL OR NEW.study_id IS DISTINCT FROM p.study_id OR NEW.actor_user_id IS DISTINCT FROM p.receiver_user_id OR NEW.actor_user_id=d.actor_user_id\n  OR NEW.created_at<d.created_at OR NEW.created_at<s.window_start OR NEW.created_at>=s.window_end\n  OR EXISTS(SELECT 1 FROM cehub_project.value_measurement_closures WHERE tenant_id=NEW.tenant_id AND workpack_id=NEW.workpack_id)\n  OR EXISTS(SELECT 1 FROM cehub_project.value_measurement_deliveries WHERE tenant_id=NEW.tenant_id AND workpack_id=NEW.workpack_id AND round>d.round)\n THEN RAISE EXCEPTION 'Only the independent named receiver may decide the current delivery'; END IF;\n IF receiver_grant.id IS DISTINCT FROM NEW.receiver_consent_id OR receiver_grant.id IS DISTINCT FROM d.receiver_consent_id OR receiver_grant.status IS DISTINCT FROM 'consented' OR NOT receiver_grant.activity_and_aggregate_use_confirmed OR receiver_grant.created_at>NEW.created_at\n  OR sender_grant.id IS DISTINCT FROM d.deliverer_consent_id OR sender_grant.status IS DISTINCT FROM 'consented' OR NOT sender_grant.activity_and_aggregate_use_confirmed\n THEN RAISE EXCEPTION 'Reception must retain the exact current original participant grants'; END IF;\n RETURN NEW;\nEND $$;\nCREATE FUNCTION cehub_project.guard_value_closure() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$\nDECLARE p cehub_project.value_measurement_workpacks;\nDECLARE s cehub_project.value_measurement_studies;\nBEGIN\n PERFORM 1 FROM cehub_project.projects WHERE tenant_id=NEW.tenant_id AND id=NEW.project_id FOR UPDATE;\n SELECT * INTO p FROM cehub_project.value_measurement_workpacks WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.workpack_id;\n SELECT * INTO s FROM cehub_project.value_measurement_studies WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=p.study_id;\n IF p.id IS NULL OR NEW.created_at<p.created_at OR NEW.created_at<s.window_start OR NEW.created_at>=s.window_end\n  OR EXISTS(SELECT 1 FROM cehub_project.value_measurement_receptions r WHERE r.tenant_id=NEW.tenant_id AND r.workpack_id=NEW.workpack_id AND (r.decision='accepted' OR r.created_at>NEW.created_at))\n  OR EXISTS(SELECT 1 FROM cehub_project.value_measurement_deliveries d WHERE d.tenant_id=NEW.tenant_id AND d.workpack_id=NEW.workpack_id AND d.created_at>NEW.created_at)\n THEN RAISE EXCEPTION 'Failure/cancellation must close an unaccepted current observation scope'; END IF;\n RETURN NEW;\nEND $$;\n"

