def upgrade() -> None:
    op.execute(DDL)
    op.execute(GUARDS)
    for table, suffix in GUARD_TABLES:
        op.execute(
            f"CREATE TRIGGER guard_{table} BEFORE INSERT ON cehub_project.{table} FOR EACH ROW EXECUTE FUNCTION cehub_project.guard_value_{suffix}()"
        )
        op.execute(f"REVOKE ALL ON FUNCTION cehub_project.guard_value_{suffix}() FROM PUBLIC")
    op.execute(
        "CREATE CONSTRAINT TRIGGER guard_value_workpack_full_roster AFTER INSERT ON cehub_project.value_measurement_workpacks DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cehub_project.guard_value_workpack_roster()"
    )
    op.execute("REVOKE ALL ON FUNCTION cehub_project.guard_value_workpack_roster() FROM PUBLIC")
    for table in TABLES:
        op.execute(
            f"CREATE TRIGGER immutable_{table} BEFORE UPDATE OR DELETE ON cehub_project.{table} FOR EACH ROW EXECUTE FUNCTION cehub_ai.protect_checkpoint_history()"
        )
        op.execute(f"REVOKE ALL ON cehub_project.{table} FROM PUBLIC")


